steps.action:
curl -s -X POST https://slack.com/api/conversations.list \
  -d "token=<TOKEN>" \
  -d "types=public_channel" \
  -d "limit=200" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if ch['name'] == 'general':
            print(ch['id'], ch['name'])
else:
    print('Error:', data)
"
